from taf.nms.nsp.nfmp.provider import NfmpProvider


class NfmpConnectionFacade(object):
    """
    Facade class to choose NFMP by version and provide related interfaces
    """

    def __init__(self, ip, username, password, port=8443, nfmp_version=19):
        """
        :param str ip: ip_address: ie. 10.108.141.24
        :param str, username: username to authenticate to NFMP
        :param str, password: password to authenticate to NFMP
        :param int port: ie. 8443
        :param nfmp_version: version of NFMP, ie. 18, '18A', 19, '19A'
        :type nfmp_version: int or str
        """
        self._nfmp = NfmpProvider.discover_nfmp(ip, username, password, port, nfmp_version)

    def reset_mrbts(self, site_id):
        self._nfmp.reset_mrbts(site_id)

    def change_nrcell_administrative_state(self, site_id, state):
        """
        To change administrative state of NRCELL with specified site id

        :param str site_id: id of site(MRBTS), ie. MRBTS-1900
        :param int state: ie. 0 is "Locked", 1 is "Unlocked" and 2 is "Shutting Down"
        :return: NRCELL info
        :rtype: dict
        """
        return self._nfmp.change_nrcell_administrative_state(site_id, state)

    def get_alarms(self):
        """
        To get all alarms info within NFMP

        :return: alarms info
        :rtype: list, list of dicts
        """
        return self._nfmp.get_alarms()

    def get_mrbts_component_general_info(self, site_id):
        """
        To get specific mrbts general info.

        :param str site_id: id of site(MRBTS), ie. MRBTS-1900
        :return: mrbts general info
        :rtype: dict
        """
        return self._nfmp.get_mrbts_component_general_info(site_id, None)

    def get_hw_component_general_info(self, site_id, module_id):
        """
        To get HW component general info.

        :param str site_id: id of site(MRBTS), ie. MRBTS-1900
        :param int module_id: id number of HW, default 1
        :return: HW component general info
        :rtype: dict
        """
        return self._nfmp.get_hw_component_general_info(site_id, module_id)

    def get_cabinet_component_general_info(self, site_id, module_id):
        """
        To get CABINET component general info.

        :param str site_id: id of site(MRBTS), ie. MRBTS-1900
        :param int module_id: id number of CABINET, default 1
        :return: CABINET component general info
        :rtype: dict
        """
        return self._nfmp.get_cabinet_component_general_info(site_id, module_id)

    def get_smod_inv_component_general_info(self, site_id, module_id):
        """
        To get SMOD component general info.

        :param str site_id: id of site(MRBTS), ie. MRBTS-1900
        :param int module_id: id number of SMOD, default 1
        :return: SMOD component general info
        :rtype: dict
        """
        return self._nfmp.get_smod_inv_component_general_info(site_id, module_id)

    def get_fan_inv_component_general_info(self, site_id, module_id):
        """
        To get FAN component general info.

        :param str site_id: id of site(MRBTS), ie. MRBTS-1900
        :param int module_id: id number of FAN, default 1
        :return: FAN component general info
        :rtype: dict
        """
        return self._nfmp.get_fan_inv_component_general_info(site_id, module_id)

    def get_gnsse_inv_component_general_info(self, site_id, module_id):
        """
        To get GNSSE component general info.

        :param str site_id: id of site(MRBTS), ie. MRBTS-1900
        :param int module_id: id number of GNSSE, default 1
        :return: GNSSE component general info
        :rtype: dict
        """
        return self._nfmp.get_gnsse_inv_component_general_info(site_id, module_id)

    def get_rmod_inv_component_general_info(self, site_id, module_id):
        """
        To get RMOD component general info.

        :param str site_id: id of site(MRBTS), ie. MRBTS-1900
        :param int module_id: id number of RMOD, default 1
        :return: RMOD component general info
        :rtype: dict
        """
        return self._nfmp.get_rmod_inv_component_general_info(site_id, module_id)

    def get_passdev_inv_component_general_info(self, site_id, module_id):
        """
        To get PASSDEV component general info.

        :param str site_id: id of site(MRBTS), ie. MRBTS-1900
        :param int module_id: id number of PASSDEV, default 1
        :return: PASSDEV component general info
        :rtype: dict
        """
        return self._nfmp.get_passdev_inv_component_general_info(site_id, module_id)

    def set_vnf_to_active(self, bts_id):
        """
        Sets given VNF state to active.

        :param str bts_id: ie. "MRBTS-1900"

        :return: None
        """
        return self._nfmp.set_vnf_to_active(bts_id=bts_id)

    def set_vnf_to_standby(self, bts_id):
        """
        Sets given VNF state to standby.

        :param str bts_id: ie. "MRBTS-1900"

        :return: None
        """
        return self._nfmp.set_vnf_to_standby(bts_id=bts_id)

    def update_from_peer_node(self, bts_id):
        """
        Updates configuration of a given node from an active node.

        :param str bts_id: ie. "MRBTS-1900"

        :return: None
        """
        return self._nfmp.update_from_peer_node(bts_id=bts_id)
